internal object TodayStudentActions {
 data class Person(val id:String,val name:String)
 fun people(event:JSONObject?):List<Person>{
  if(event==null||event.optString("type")!="Personal"||event.optString("id").isBlank()||!Regex("([01]\\d|2[0-3]):[0-5]\\d").matches(event.optString("start")))return emptyList()
  val ids=event.optJSONArray("studentIds")?:return emptyList();val names=event.optJSONArray("studentNames")?:return emptyList()
  if(ids.length()!=names.length()||ids.length() !in 1..80)return emptyList()
  val result=(0 until ids.length()).map{Person(ids.optString(it),names.optString(it))}
  return if(result.any{it.id.isBlank()||it.id=="null"||it.id.length>256||it.name.isBlank()}||result.map{it.id}.distinct().size!=result.size)emptyList()else result
 }
 fun path(event:JSONObject,person:Person,action:String):String{
  require(action in listOf("register","presence","absence"));val date=event.getString("date");val time=event.getString("start")
  require(Regex("([01]\\d|2[0-3]):[0-5]\\d").matches(time));WidgetNavigation.path("event",date,event.getString("id"))
  return Uri.Builder().path("/app/widget-action").appendQueryParameter("widget","student-action").appendQueryParameter("date",date).appendQueryParameter("id",event.getString("id")).appendQueryParameter("studentId",person.id).appendQueryParameter("action",action).appendQueryParameter("time",time).build().toString()
 }
 /** One line and three 44dp touch targets per student. */
 fun rowHeight(count:Int)=44
 fun height(c:Context,size:WidgetLayout,date:String,event:JSONObject):Int =
  44+2+44*people(event).size.coerceAtMost(3)+(if(people(event).size>3)26 else 0)
 /** Only a single exact student state may unlock pending actions. Unknown stays read-only. */
 fun mode(event:JSONObject,id:String):String{
  val states=event.optJSONArray("studentStates")
  val matches=if(states==null)emptyList()else (0 until states.length()).mapNotNull{states.optJSONObject(it)}.filter{it.optString("studentId")==id}
  if(matches.size!=1)return "unknown"
  val record=matches.single()
  return when(AgendaProgress.state(event,id)){
   "absent"->"absence"
   "present"->if(record.optBoolean("registered"))"registered"else "presence"
   "pending"->if(record.optBoolean("registered")||record.has("sessionId"))"unknown"else "pending"
   else->if(record.optString("reason")=="unlinked-record"&&record.optBoolean("confirmedDayPresence")&&!record.optBoolean("registered")&&!record.has("sessionId"))"day-presence"else "unknown"
  }
 }
 private fun stateLabel(mode:String)=when(mode){"absence"->"Ausência confirmada";"registered"->"Treino registrado; presença confirmada";"presence"->"Presença confirmada; sem treino registrado";"day-presence"->"Presença confirmada no dia; sem vínculo informado com esta aula e sem treino registrado";"pending"->"Pendente";else->"Estado da ocorrência não confirmado. Consulte os registros e atualize"}
 private fun namePaint(c:Context,id:Int,sp:Float)=android.text.TextPaint().apply{typeface=android.graphics.Typeface.create("sans-serif-medium",android.graphics.Typeface.NORMAL);textSize=TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_SP,sp*WidgetTypography.factor(c,id),c.resources.displayMetrics)}
 internal fun fittedName(c:Context,id:Int,full:String,label:String,space:Float):Pair<String,Float>{
  val paint=namePaint(c,id,11.5f);val floor=namePaint(c,id,9.5f)
  // Text layout rounds glyph advances to pixels. Do not fit exactly on the ellipsis boundary.
  val available=(kotlin.math.floor(space)-5*c.resources.displayMetrics.density).coerceAtLeast(1f)
  val parts=full.trim().split(Regex("\\s+"));val last=parts.lastOrNull().orEmpty();val first=parts.firstOrNull().orEmpty()
  val initial=first.codePoints().toArray().take(1).map{String(Character.toChars(it))}.joinToString("")
  val shortFirst=first.codePoints().toArray().take(4).map{String(Character.toChars(it))}.joinToString("")
  val surnameInitial=last.codePoints().toArray().take(1).map{String(Character.toChars(it))}.joinToString("")
  val candidates=(listOf(full,"$first $last","$first $surnameInitial.")+(first.length downTo 1).map{first.take(it)+". $surnameInitial."}).distinct()
  val chosen=candidates.firstOrNull{floor.measureText(it)<=available}?:initial
  val target=(paint.textSize*minOf(1f,available/paint.measureText(chosen).coerceAtLeast(1f))).coerceAtLeast(floor.textSize)
  return chosen to target
 }
 @android.annotation.TargetApi(31)
 fun attach(c:Context,v:RemoteViews,id:Int,size:WidgetLayout,event:JSONObject,height:Int){
  v.setViewVisibility(R.id.next_title,View.GONE);v.setViewVisibility(R.id.next_type,View.GONE);v.setViewVisibility(R.id.next_students,View.VISIBLE)
  v.removeAllViews(R.id.next_students)
  val people=people(event);val labels=AgendaNames.labels(people.map{it.name});val density=c.resources.displayMetrics.density
  val rowWidth=((size.width-20)*density).coerceAtLeast(1f)
  val buttonWidth=44
  for(person in people.take(3)){
   val row=RemoteViews(c.packageName,R.layout.today_student)
   row.setViewLayoutHeight(R.id.student_row,rowHeight(people.size).toFloat(),TypedValue.COMPLEX_UNIT_DIP)
   val status=mode(event,person.id);val pending=status=="pending"
   val fitted=fittedName(c,id,person.name,labels[person.name]?:person.name,rowWidth-(3*buttonWidth)*density)
   row.setTextViewText(R.id.student_name,fitted.first);row.setTextViewTextSize(R.id.student_name,TypedValue.COMPLEX_UNIT_PX,fitted.second)
   row.setContentDescription(R.id.student_name,person.name+", "+stateLabel(status)+". Estado da última sincronização.")
   for((button,action,label)in listOf(Triple(R.id.student_register,"register","Registrar treino de"),Triple(R.id.student_presence,"presence","Confirmar presença de"),Triple(R.id.student_absence,"absence","Confirmar ausência de"))){
    row.setViewVisibility(button,View.VISIBLE);row.setBoolean(button,"setEnabled",pending);row.setInt(button,"setImageAlpha",if(pending||(action=="presence"&&status in listOf("presence","registered","day-presence"))||(action=="absence"&&status=="absence")||(action=="register"&&status=="registered"))255 else 80)
    row.setViewLayoutWidth(button,buttonWidth.toFloat(),TypedValue.COMPLEX_UNIT_DIP)
    val side=kotlin.math.round((buttonWidth-18)*density/2f).toInt();val vertical=kotlin.math.round(7*density).toInt();row.setViewPadding(button,side,vertical,side,vertical)
    row.setContentDescription(button,"$label ${person.name}, ${event.optString("date")}, ${event.optString("start")}")
    if(pending)row.setOnClickPendingIntent(button,WidgetNavigation.open(c,id,"${event.optString("id")}:${event.optString("date")}:${person.id}:$action",path(event,person,action)))
   }
   row.setViewVisibility(R.id.student_state,View.GONE)
   row.setOnClickPendingIntent(R.id.student_name,WidgetNavigation.open(c,id,"student:${event.optString("id")}:${person.id}",WidgetNavigation.path("student",event.getString("date"),person.id)))
   v.addView(R.id.next_students,row)
  }
  if(people.size>3){val more=RemoteViews(c.packageName,R.layout.widget_small_card);more.setTextViewText(R.id.small_text,"+${people.size-3} alunos · abrir aula");more.setOnClickPendingIntent(R.id.small_text,WidgetNavigation.open(c,id,"more-students",WidgetNavigation.record(event)));v.addView(R.id.next_students,more)}
 }
